def dfs(graph, start, end, path=[]):
    path = path + [start]
    if start == end:
        return path
    if start not in graph:
        return None

    for node in graph[start]:
        if node not in path:
            new_path = dfs(graph, node, end, path)
            if new_path: return new_path

    return None

