class Graph:
    def __init__(self):
        self.adjacency_list = {}

    def add_edge(self, vertex1, vertex2):
        if vertex1 in self.adjacency_list:
            self.adjacency_list[vertex1].append(vertex2)
        else:
            self.adjacency_list[vertex1] = [vertex2]

        if vertex2 in self.adjacency_list:
            self.adjacency_list[vertex2].append(vertex1)
        else:
            self.adjacency_list[vertex2] = [vertex1]

    def dfs_search(self, start_vertex, target_vertex):
        visited = {start_vertex: None}  # Dictionary to keep track of visited nodes
        stack = [start_vertex]  # Use a stack to implement DFS

        while stack:
            current_vertex = stack.pop()
            if current_vertex == target_vertex:
                return visited
            for neighbor in self.adjacency_list[current_vertex]:
                if neighbor not in visited:
                    visited[neighbor] = current_vertex
                    stack.append(neighbor)

        return None  # If no path is found

def validate_connected_graph(graph, vertices):
    visited = set()
    def dfs_check(current_vertex):
        visited.add(current_vertex)
        for neighbor in graph.adjacency_list.get(current_vertex, []):
            if neighbor not in visited:
                dfs_check(neighbor)

    for v in vertices:
        if v not in visited:
            dfs_check(v)
    return len(visited) == len(vertices)

# Example usage:
